local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local CommonGoodsListScr = "Game.Behaviours.CommonGoodsList"
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
local cookingComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CookingComponent)
local CriWareUtils =  import('Game.Entry.CriWareUtilsFix')
local Canvas = CS.UnityEngine.Canvas

---@class UIFishHarvestDisPlayPopupDialog
local UIFishHarvestDisPlayPopupDialog = Class("UIFishHarvestDisPlayPopupDialog")

function UIFishHarvestDisPlayPopupDialog:__init() 
    self._data = nil
    self._rewards = {}
end

function UIFishHarvestDisPlayPopupDialog:__delete()
    self._data = nil
    self._rewards = {}
end

function UIFishHarvestDisPlayPopupDialog:Awake()
    SetButtonAction(self.ImgBackground, Bind(self, self.OnBtnClose))
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._data = checkTable(argument.data)
    self._lastExp = checkNumber(argument.lastExp)
    self._lastLevel = checkNumber(argument.lastLevel)
    self.closeCb = (argument.closeCb)
    self._fishPlaceId = checkNumber(argument.fishPlaceId)    

    if not self._data then
        return
    end

    self:FillSelf()
end

function UIFishHarvestDisPlayPopupDialog:FillSelf()
    --if FishingUtils.GetGuideFishId() == checkNumber(self._data.fishId) then
    --    KTool.SetActive(self.LayoutHistory, false)
    --    KTool.SetActive(self.LayoutHarvest, false)
    --end

    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.fishId)
    if vo then
        CfUtils.FillText(self.TextTitle, vo.name)
        CfUtils.FillImage(self.ImgIconFish, vo.photoPath)
        CfUtils.FillText(self.Root.transform:Find("FishHarvest/CommonHarvest/FishIconGroup/Explain/TextDesc"), vo.description)
    end
    vo = FishingUtils.GetFishingSpeciesVo(self._data.fishId)
    if vo then
        local go = self.ParticleRoot.transform:Find("UIFX_FishHarvestFishQuality_"..vo.rare)
        if go then
            KTool.SetActive(go, true)
        end

        local num = 0
        local ratingVo = FishingUtils.GetFishingRatingVo(self._data.rating)
        if ratingVo then
            num = num + (math.floor(vo.price * (1 + ratingVo.priceAddition)) * 1)
        end
        
        for k, v in pairs(self._data.rewards) do
            if (checkNumber(v.goodsId) == Constants.Currency.GoldId) then
                num = v.num
            end
        end
        CfUtils.FillText(self.TextNumberSell, "+"..num)
        local path = GoodsConfMgr:GetInstance():GetPhotoPathById(vo.currency)
        CfUtils.FillImage(self.ImgIconSell, path)
    end

    CfUtils.FillText(self.TextRare, FishingUtils.GetFishRareNameByRare(self._data.rating))
    CfUtils.FillText(self.TextLength, (self._data.length / 100).."CM")

    CfUtils.FillText(self.TextNumber, (checkNumber(self._data.record) / 100).."CM")
    CfUtils.FillText(self.TextAllGet, self._data.getNum)
    CfUtils.FillText(self.TextExp, (checkNumber(self._data.fishExp) - self._lastExp))
    CfUtils.SetUISwitchImage(self.ImgIcon, FishingUtils.GetFishRareNameByRare(self._data.rating) == "S" and 2 or 1)
    CfUtils.SetUISwitchImage(self.TextGrade, self._data.rating)

    KTool.SetActive(self.ImgNew, checkNumber(self._data.isNew) == 1)

    self._rewards = {}
    for k, v in pairs(self._data.rewards) do
        local type = GoodsUtils.GetIdType(v.goodsId)
        if (checkNumber(v.goodsId) ~= Constants.Currency.GoldId) and (type ~= Constants.IDType.GoodsFish) and (type ~= Constants.IDType.RestaurantRecipeGoods) then
            table.insert(self._rewards, v)
        end
    end
    if self._rewards and table.count(self._rewards) > 0 then
        self.RewardList:InitGridView(table.count(self._rewards), Bind(self, self.OnRefreshIndex))
        KTool.SetActive(self.UnexpectedHarvest, true)
    else
        KTool.SetActive(self.UnexpectedHarvest, false)
    end

    local isActivity = FishingUtils.IsFishPlaceActivitying(self._fishPlaceId)
    CfUtils.SetActive(self.IntegralGet, checkNumber(self._data.activityScore) > 0)
    if isActivity then
        CfUtils.FillText(self.TxtGetNumber, checkNumber(self._data.activityScore))
    end

    CfUtils.SetActive(self.ConditionRemind, checkNumber(self._data.activityTaskId) > 0)
    if checkNumber(self._data.activityTaskId) > 0 then
        local vo = FishingUtils.GetFishingTaskVo(self._data.activityTaskId)
        CfUtils.FillText(self.TextDesc, string.gsub(vo.desc2, "\\n", "\n"))

        GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishActivityTask, 1)
    end

    vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.fishId)
    if vo then
        local parGo = self.Root.transform:Find("FishHarvest/CommonHarvest/FishIconGroup/StarLevel")
        local childGo = parGo.transform:Find("ImgStar")

        local num = checkNumber(vo.quality)
        for i = 1, num do
            local go = parGo.transform:Find("go"..i)
            if isNull(go) then
                go = CfUtils.InstantiateGo(childGo, parGo)
                go.name = "go"..i
            end
            CfUtils.SetActive(go, true)
        end  
    end
end

function UIFishHarvestDisPlayPopupDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local data = self._rewards[index + 1]

    CfUtils.RefeshGoodGo(cell.gameObject.transform:Find("GoodNode"), data.goodsId, data.num, 0.55, nil, function()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
        GameUtils.ShowCommonTipsBoard(cell.gameObject, vo.name, nil, vo.quality, data.goodsId)
    end)

    return cell
end

function UIFishHarvestDisPlayPopupDialog:OnBtnClose()
    if not self._isCanClose then
        cs_coroutine.stop(self._co)
        self._isCanClose = true
        self._isClose = true
        local animator = KTool.GetComponent(self.Root.gameObject, typeof(CS.UnityEngine.Animator))
        if not isNull(animator) then
            animator:SetTrigger("Skip")
        end
        cs_coroutine.start(function()
            coroutine.yield(WaitForSeconds(0.5))
            self._isClose = false
        end)
        return
    end
    if self._isClose then
        return
    end
    self._isClose = true

    local data = self._data

    UIModule.CloseDialog(self.controller)
    local vo = FishingUtils.GetFishingSpeciesVo(data.fishId)

    local isUnlock = false
    if checkNumber(vo.unlock) > 0 then
        --local foodVo = CookingUtils.GetBattleCookingFoodVo(vo.unlock)

        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local dojo = maidCoffeePlayerComponent:GetRecipeDoJoById(vo.unlock)
        local isHaveMenu = (dojo ~= nil)
        if not isHaveMenu then
            isUnlock = true
            maidCoffeePlayerComponent:UpdateThingNo(vo.unlock)
        end
    end

    --有彩蛋
    if checkNumber(data.easterEgg) > 0 then
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolGetCollectionPopupDialog, parameters = {
            cb = function()
                self.closeCb()
            end, data = data, lastLevel = self._lastLevel
        }})
    elseif isUnlock then
        --- 食谱解锁
        if self.closeCb then
            self.closeCb()
        end
        data.goodsId = vo.unlock

        UIModule.OpenDialog({ id = Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel, parameters = {
            data = data,
            levelUpType = Constants.UICultivateLevelUpFinishType.GetRecipe,
            UITypeId = Constants.UITypeIds.UIFishHarvestDisPlayPopupDialog
        }})
    elseif checkNumber(data.driftBottle.id) > 0 then
        if FishingUtils.IsAutoing() then
            if self.closeCb then
                self.closeCb()
            end
        else
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolDriftingBottleDialog, parameters = {
                data = data,
                cb = function()
                    if self.closeCb then
                        self.closeCb()
                    end
                end
            }})
        end
    else
        if self.closeCb then
            self.closeCb()
        end
        if checkNumber(data.fishLevel) > self._lastLevel then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateLevelUpFinishDialog, parameters = {
                lastLevel = self._lastLevel,
                curLevel = data.fishLevel,
                levelUpType = Constants.UICultivateLevelUpFinishType.FishLevel
            }})
        end
    end
end

function UIFishHarvestDisPlayPopupDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, true)
        
        -- drawcall优化 降低批次
        local lastDialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UIFishPoolGoFishingDialog)
        if lastDialog then
            self._canvas = lastDialog.gameObject:GetComponent(typeof(Canvas))
            if self._canvas then
                self._canvas.enabled = false
            end
        end

        self._co = cs_coroutine.start(function()
            coroutine.yield(WaitForSeconds(3))
            self._isCanClose = true

            if FishingUtils.IsAutoing() then
                coroutine.yield(WaitForSeconds(FishingUtils.GetAutoPageWaitTime()))
                self:OnBtnClose()
            end
        end)

        local rainScreen = KTool.GetOrAddComponent(self.Root.gameObject, typeof(CS.RainScreen))
        if rainScreen then
            self._loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Shaders/Scene/RainScreen/RainScreen.mat", nil, true)
            if self._loader.IsSuccess then
                self._go = CS.UnityEngine.GameObject.Instantiate(self._loader.ResultObject)
                rainScreen.RainScreenMaterial = self._go
            end
        end
    end))
    return coWait
end

function UIFishHarvestDisPlayPopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self._canvas then
            self._canvas.enabled = true
        end

        if not isNull(self._loader) then
            self._loader:Release(true)
        end
        if not isNull(self._go) then
            CS.UnityEngine.GameObject.Destroy(self._go)
        end

        if self._co then 
            cs_coroutine.stop(self._co)
            self._co = nil
        end

        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFishHarvestDisPlayPopupDialog
